window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-53397532d0c369cc"]={"versions": [{"id": "FIG-53397532d0c369cc", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR Adaptive Platform (Manifest-Modellierung). Dargestellt ist der strukturelle Metamodell-Kontext für die Instanziierung des Intrusion Detection System Managers (<code>IdsmModuleInstantiation</code>) und dessen Einbettung in die Modul-, Plattform- und Endpunkt-Konfigurationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Modellelemente und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>AdaptiveModuleInstantiation</code> (abstrakt, spezialisiert <code>Identifiable</code>).</li>\n<li><code>NonOsModuleInstantiation</code> (spezialisiert <code>AdaptiveModuleInstantiation</code>).</li>\n<li><code>IdsPlatformInstantiation</code> (abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>): Besitzt eine gerichtete Assoziation <code>+networkInterface</code> mit Kardinalität <code>0..1</code> auf <code>PlatformModuleEthernetEndpointConfiguration</code>.</li>\n<li><code>IdsmModuleInstantiation</code> (spezialisiert <code>IdsPlatformInstantiation</code>): Konkrete Instanziierungsklasse des IDS-Managers.</li>\n<li><code>IdsmInstance</code> (spezialisiert <code>IdsCommonElement</code>): Besitzt die Attribute <code>+idsmInstanceId: PositiveInteger [0..1]</code> und <code>+timestampFormat: String [0..1]</code>. Eine gerichtet aggregierende Assoziation führt mit Rollenbezeichnung <code>+idsmModuleInstantiation</code>, Multiplizität <code>0..1</code> und Stereotyp <code>«atpSplitable»</code> von <code>IdsmInstance</code> zu <code>IdsmModuleInstantiation</code>.</li>\n<li><code>PlatformModuleEndpointConfiguration</code> (abstrakt, spezialisiert <code>ARElement</code>).</li>\n<li><code>PlatformModuleEthernetEndpointConfiguration</code> (spezialisiert <code>PlatformModuleEndpointConfiguration</code>): Besitzt die Attribute <code>+ipv4MulticastIpAddress: Ip4AddressString [0..1]</code>, <code>+ipv6MulticastIpAddress: Ip6AddressString [0..1]</code>, <code>+tcpPort: PositiveInteger [0..1]</code> und <code>+udpPort: PositiveInteger [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Das Diagramm definiert Deklarations- und Referenzierungsstrukturen für die Manifest-Konfiguration zur Entwurfs- und Bereitstellungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für AUTOSAR-Manifeste zur Konfiguration des Intrusion Detection System Managers auf Adaptive Plattformen. Definiert die Konfigurationsattribute für Netzwerkendpunkte (Multicast-IPs und Ports) sowie die Identifikation und das Zeitstempelformat einer IDS-Manager-Instanz. Die Kennzeichnung <code>«atpSplitable»</code> erlaubt die Verteilung der Instanzreferenzen über mehrere ARXML-Dateien.</p>"}, {"id": "FIG-b044836a9c6c95e2", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR Adaptive Platform (Manifest-Modellierung). Dargestellt ist der strukturelle Metamodell-Kontext für die Instanziierung des Intrusion Detection System Managers (<code>IdsmModuleInstantiation</code>) und dessen Einbettung in die Modul-, Plattform- und Endpunkt-Konfigurationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Modellelemente und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>AdaptiveModuleInstantiation</code> (abstrakt, spezialisiert <code>Identifiable</code>).</li>\n<li><code>NonOsModuleInstantiation</code> (spezialisiert <code>AdaptiveModuleInstantiation</code>).</li>\n<li><code>IdsPlatformInstantiation</code> (abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>): Besitzt eine gerichtete Assoziation <code>+networkInterface</code> mit Kardinalität <code>0..1</code> auf <code>PlatformModuleEthernetEndpointConfiguration</code>.</li>\n<li><code>IdsmModuleInstantiation</code> (spezialisiert <code>IdsPlatformInstantiation</code>): Konkrete Instanziierungsklasse des IDS-Managers.</li>\n<li><code>IdsmInstance</code> (spezialisiert <code>IdsCommonElement</code>): Besitzt die Attribute <code>+idsmInstanceId: PositiveInteger [0..1]</code> und <code>+timestampFormat: String [0..1]</code>. Eine gerichtet aggregierende Assoziation führt mit Rollenbezeichnung <code>+idsmModuleInstantiation</code>, Multiplizität <code>0..1</code> und Stereotyp <code>«atpSplitable»</code> horizontal von <code>IdsmInstance</code> zu <code>IdsmModuleInstantiation</code>.</li>\n<li><code>PlatformModuleEndpointConfiguration</code> (abstrakt, spezialisiert <code>ARElement</code>).</li>\n<li><code>PlatformModuleEthernetEndpointConfiguration</code> (spezialisiert <code>PlatformModuleEndpointConfiguration</code>): Besitzt die Attribute <code>+ipv4MulticastIpAddress: Ip4AddressString [0..1]</code> und <code>+ipv6MulticastIpAddress: Ip6AddressString [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Das Diagramm definiert Deklarations- und Referenzierungsstrukturen für die Manifest-Konfiguration zur Entwurfs- und Bereitstellungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für AUTOSAR-Manifeste zur Konfiguration des Intrusion Detection System Managers auf Adaptive Plattformen. Definiert die Adressierungsattribute für Multicast-Netzwerkendpunkte (IPv4/IPv6 ohne Port-Attribute) sowie die Identifikation und das Zeitstempelformat einer IDS-Manager-Instanz. Die Kennzeichnung <code>«atpSplitable»</code> erlaubt die Verteilung der Instanzreferenzen über mehrere ARXML-Dateien.</p>"}, {"id": "FIG-de1cc88040ba2a57", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR Adaptive Platform (Manifest-Modellierung). Dargestellt ist der strukturelle Metamodell-Kontext für die Instanziierung des Intrusion Detection System Managers (<code>IdsmModuleInstantiation</code>) und dessen Einbettung in die Modul-, Plattform- und Endpunkt-Konfigurationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Modellelemente und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>AdaptiveModuleInstantiation</code> / <code>NonOsModuleInstantiation</code> als abstrakte Basisklassen.</li>\n<li><code>IdsPlatformInstantiation</code> (abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>): Besitzt eine gerichtete Assoziation <code>+networkInterface</code> mit Kardinalität <code>0..*</code> auf <code>PlatformModuleEthernetEndpointConfiguration</code>.</li>\n<li><code>IdsmModuleInstantiation</code> (spezialisiert <code>IdsPlatformInstantiation</code>): Konkrete Instanziierungsklasse des IDS-Managers.</li>\n<li><code>IdsmInstance</code> (spezialisiert <code>IdsCommonElement</code>): Besitzt die Attribute <code>+idsmInstanceId: PositiveInteger [0..1]</code> und <code>+timestampFormat: String [0..1]</code>. Eine gerichtet aggregierende Assoziation führt mit Rollenbezeichnung <code>+idsmModuleInstantiation</code>, Multiplizität <code>0..1</code> und Stereotyp <code>«atpSplitable»</code> horizontal von <code>IdsmInstance</code> zu <code>IdsmModuleInstantiation</code>.</li>\n<li><code>PlatformModuleEndpointConfiguration</code> (abstrakt, spezialisiert <code>ARElement</code>).</li>\n<li><code>PlatformModuleEthernetEndpointConfiguration</code> (spezialisiert <code>PlatformModuleEndpointConfiguration</code>): Besitzt die Attribute <code>+ipv4MulticastIpAddress: Ip4AddressString [0..1]</code> und <code>+ipv6MulticastIpAddress: Ip6AddressString [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Das Diagramm definiert Deklarations- und Referenzierungsstrukturen für die Manifest-Konfiguration zur Entwurfs- und Bereitstellungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für AUTOSAR-Manifeste zur Konfiguration des Intrusion Detection System Managers auf Adaptive Plattformen. Ermöglicht die Zuordnung von mehreren Ethernet-Netzwerk-Endpunkten (<code>0..*</code>) zur Plattform-Instanziierung. Die Kennzeichnung <code>«atpSplitable»</code> erlaubt die Verteilung der Instanzreferenzen über mehrere ARXML-Dateien.</p>"}, {"id": "FIG-cacc0d41854caf36", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR Adaptive Platform (Manifest-Modellierung). Dargestellt ist der strukturelle Metamodell-Kontext für die Instanziierung des Intrusion Detection System Managers (<code>IdsmModuleInstantiation</code>) und dessen Einbettung in die Modul-, Plattform- und Endpunkt-Konfigurationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Modellelemente und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>AdaptiveModuleInstantiation</code> / <code>NonOsModuleInstantiation</code> als abstrakte Basisklassen.</li>\n<li><code>IdsPlatformInstantiation</code> (abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>): Besitzt eine gerichtete Assoziation <code>+networkInterface</code> mit Kardinalität <code>0..*</code> auf <code>PlatformModuleEthernetEndpointConfiguration</code>.</li>\n<li><code>IdsmModuleInstantiation</code> (spezialisiert <code>IdsPlatformInstantiation</code>): Konkrete Instanziierungsklasse des IDS-Managers.</li>\n<li><code>IdsmInstance</code> (spezialisiert <code>IdsCommonElement</code>): Besitzt die Attribute <code>+idsmInstanceId: PositiveInteger [0..1]</code> und <code>+timestampFormat: String [0..1]</code>. Eine gerichtet aggregierende Assoziation führt mit Rollenbezeichnung <code>+idsmModuleInstantiation</code>, Multiplizität <code>0..1</code> und Stereotyp <code>«atpSplitable»</code> horizontal von <code>IdsmInstance</code> zu <code>IdsmModuleInstantiation</code>.</li>\n<li><code>PlatformModuleEndpointConfiguration</code> (abstrakt, spezialisiert <code>ARElement</code>).</li>\n<li><code>PlatformModuleEthernetEndpointConfiguration</code> (spezialisiert <code>PlatformModuleEndpointConfiguration</code>): Besitzt die Attribute <code>+ipv4MulticastIpAddress: Ip4AddressString [0..1]</code> und <code>+ipv6MulticastIpAddress: Ip6AddressString [0..1]</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Das Diagramm definiert Deklarations- und Referenzierungsstrukturen für die Manifest-Konfiguration zur Entwurfs- und Bereitstellungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für AUTOSAR-Manifeste zur Konfiguration des Intrusion Detection System Managers auf Adaptive Plattformen. Ermöglicht die Zuordnung von mehreren Ethernet-Netzwerk-Endpunkten (<code>0..*</code>) zur Plattform-Instanziierung. Die Kennzeichnung <code>«atpSplitable»</code> erlaubt die Verteilung der Instanzreferenzen über mehrere ARXML-Dateien.</p>"}, {"id": "FIG-4cc2de773ba2c18d", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR Adaptive Platform (Manifest-Modellierung). Dargestellt ist der strukturelle Metamodell-Kontext für die Instanziierung des Intrusion Detection System Managers (<code>IdsmModuleInstantiation</code>) und dessen Einbettung in die Modul-, Plattform- und Endpunkt-Konfigurationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Modellelemente und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>AdaptiveModuleInstantiation</code> / <code>NonOsModuleInstantiation</code> als abstrakte Basisklassen.</li>\n<li><code>IdsPlatformInstantiation</code> (abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>): Besitzt eine gerichtete Assoziation <code>+networkInterface</code> mit Kardinalität <code>0..*</code> auf <code>PlatformModuleEthernetEndpointConfiguration</code>.</li>\n<li><code>IdsmModuleInstantiation</code> (spezialisiert <code>IdsPlatformInstantiation</code>): Konkrete Instanziierungsklasse des IDS-Managers.</li>\n<li><code>IdsmInstance</code> (spezialisiert <code>IdsCommonElement</code>): Besitzt die Attribute <code>+idsmInstanceId: PositiveInteger [0..1]</code> und <code>+timestampFormat: String [0..1]</code>. Eine gerichtet aggregierende Assoziation führt mit Rollenbezeichnung <code>+idsmModuleInstantiation</code>, Multiplizität <code>0..1</code> und Stereotyp <code>«atpSplitable»</code> horizontal von <code>IdsmInstance</code> zu <code>IdsmModuleInstantiation</code>.</li>\n<li><code>PlatformModuleEndpointConfiguration</code> (abstrakt, spezialisiert <code>ARElement</code>).</li>\n<li><code>PlatformModuleEthernetEndpointConfiguration</code> (spezialisiert <code>PlatformModuleEndpointConfiguration</code>): Attributloser Konfigurationsendpunkt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Das Diagramm definiert Deklarations- und Referenzierungsstrukturen für die Manifest-Konfiguration zur Entwurfs- und Bereitstellungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für AUTOSAR-Manifeste zur Konfiguration des Intrusion Detection System Managers auf Adaptive Plattformen. <code>PlatformModuleEthernetEndpointConfiguration</code> dient als attributlose Endpunktreferenz (<code>0..*</code>). Die Kennzeichnung <code>«atpSplitable»</code> erlaubt die Verteilung der Instanzreferenzen über mehrere ARXML-Dateien.</p>"}, {"id": "FIG-cee2f9fb90500aad", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR Adaptive Platform (Manifest-Modellierung). Dargestellt ist der strukturelle Metamodell-Kontext für die Instanziierung des Intrusion Detection System Managers (<code>IdsmModuleInstantiation</code>) und dessen Einbettung in die Modul-, Plattform- und Endpunkt-Konfigurationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert folgende Modellelemente und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>AdaptiveModuleInstantiation</code> / <code>NonOsModuleInstantiation</code> als abstrakte Basisklassen.</li>\n<li><code>IdsPlatformInstantiation</code> (abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>): Besitzt eine gerichtete Assoziation <code>+networkInterface</code> mit Kardinalität <code>0..*</code> auf <code>PlatformModuleEthernetEndpointConfiguration</code>.</li>\n<li><code>IdsmModuleInstantiation</code> (spezialisiert <code>IdsPlatformInstantiation</code>): Konkrete Instanziierungsklasse des IDS-Managers. Verfügt über eine gerichtete Assoziation <code>+reportableSecurityEvent</code> mit Multiplizität <code>0..*</code> und Stereotyp <code>«atpSplitable»</code> auf <code>SecurityEventMapping</code>.</li>\n<li><code>SecurityEventMapping</code> (spezialisiert <code>UploadableDeploymentElement</code>): Zielelement für berichtbare Sicherheitsereignisse.</li>\n<li><code>IdsmInstance</code> (spezialisiert <code>IdsCommonElement</code>): Besitzt die Attribute <code>+idsmInstanceId: PositiveInteger [0..1]</code> und <code>+timestampFormat: String [0..1]</code>. Eine gerichtet aggregierende Assoziation führt mit Rollenbezeichnung <code>+idsmModuleInstantiation</code>, Multiplizität <code>0..1</code> und Stereotyp <code>«atpSplitable»</code> horizontal von <code>IdsmInstance</code> zu <code>IdsmModuleInstantiation</code>.</li>\n<li><code>PlatformModuleEndpointConfiguration</code> (abstrakt, spezialisiert <code>ARElement</code>).</li>\n<li><code>PlatformModuleEthernetEndpointConfiguration</code> (spezialisiert <code>PlatformModuleEndpointConfiguration</code>): Attributloser Konfigurationsendpunkt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Das Diagramm definiert Deklarations- und Referenzierungsstrukturen für die Manifest-Konfiguration zur Entwurfs- und Bereitstellungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für AUTOSAR-Manifeste zur Konfiguration des Intrusion Detection System Managers auf Adaptive Plattformen. Erlaubt die Modellierung berichtbarer Sicherheitsereignisse über die <code>«atpSplitable»</code>-Assoziation zu <code>SecurityEventMapping</code> (<code>0..*</code>) zusätzlich zur Endpunktanbindung und Instanzkonfiguration. Die Aufteilung über mehrere ARXML-Dateien wird an beiden Assoziationen durch <code>«atpSplitable»</code> unterstützt.</p>"}], "trans": [{"from": "FIG-53397532d0c369cc", "to": "FIG-b044836a9c6c95e2", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>PlatformModuleEthernetEndpointConfiguration</code>: Attribute <code>tcpPort: PositiveInteger [0..1]</code> und <code>udpPort: PositiveInteger [0..1]</code> entfernt.</li>\n<li>Layout: Assoziationslinie <code>idsmModuleInstantiation</code> von <code>IdsmInstance</code> zu <code>IdsmModuleInstantiation</code> horizontal geführt (zuvor vertikal).</li>\n</ul>"}, {"from": "FIG-b044836a9c6c95e2", "to": "FIG-de1cc88040ba2a57", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Assoziation <code>networkInterface</code> (<code>IdsPlatformInstantiation</code> zu <code>PlatformModuleEthernetEndpointConfiguration</code>): Multiplizität der Zielrolle von <code>0..1</code> auf <code>0..*</code> erweitert.</li>\n<li><code>Identifiable</code>: Stereotyp bzw. Basisklasse oberhalb von <code>AdaptiveModuleInstantiation</code> in der Vererbungshierarchie entfernt (im Block zusammengefasst als <code>AdaptiveModuleInstantiation</code> / <code>NonOsModuleInstantiation</code>).</li>\n</ul>"}, {"from": "FIG-de1cc88040ba2a57", "to": "FIG-cacc0d41854caf36", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cacc0d41854caf36", "to": "FIG-4cc2de773ba2c18d", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>PlatformModuleEthernetEndpointConfiguration</code>: Attribute <code>ipv4MulticastIpAddress: Ip4AddressString [0..1]</code> und <code>ipv6MulticastIpAddress: Ip6AddressString [0..1]</code> entfernt.</li>\n</ul>"}, {"from": "FIG-4cc2de773ba2c18d", "to": "FIG-cee2f9fb90500aad", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Klasse <code>SecurityEventMapping</code> (Spezialisierung von <code>UploadableDeploymentElement</code>) hinzugefügt.</li>\n<li>Assoziation von <code>IdsmModuleInstantiation</code> zu <code>SecurityEventMapping</code> ergänzt: Rollenname <code>+reportableSecurityEvent</code>, Multiplizität <code>0..*</code>, markiert mit Stereotyp <code>«atpSplitable»</code>.</li>\n</ul>"}]};
